--
-- Estructura para la vista `vista_detalle_eventos`
--
DROP TABLE IF EXISTS `vista_detalle_eventos`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u991565456_maga_un`@`127.0.0.1` SQL SECURITY DEFINER VIEW `vista_detalle_eventos`  AS SELECT `e`.`id` AS `id`, `e`.`numero_evento` AS `numero_evento`, `e`.`titulo` AS `titulo`, `e`.`sesion_numero` AS `sesion_numero`, `e`.`fecha_hora` AS `fecha_hora`, `r`.`total_votos` AS `total_votos`, `r`.`votos_favor` AS `votos_favor`, `r`.`votos_contra` AS `votos_contra`, `r`.`votos_ausentes` AS `votos_ausentes`, `r`.`votos_licencia` AS `votos_licencia`, `r`.`resultado` AS `resultado`, `e`.`archivo_origen` AS `archivo_origen` FROM (`votaciones_eventos` `e` left join `votaciones_resumen_eventos` `r` on(`e`.`id` = `r`.`evento_id`)) ORDER BY `e`.`fecha_hora` DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vista_estadisticas_bloque`
--
DROP TABLE IF EXISTS `vista_estadisticas_bloque`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u991565456_maga_un`@`127.0.0.1` SQL SECURITY DEFINER VIEW `vista_estadisticas_bloque`  AS SELECT `b`.`id` AS `id`, `b`.`nombre` AS `nombre`, count(distinct `v`.`congresista_id`) AS `total_congresistas`, count(`v`.`id`) AS `total_votos`, sum(case when `v`.`voto` = 'A FAVOR' then 1 else 0 end) AS `votos_favor`, sum(case when `v`.`voto` = 'EN CONTRA' then 1 else 0 end) AS `votos_contra`, sum(case when `v`.`voto` = 'AUSENTE' then 1 else 0 end) AS `ausencias`, round(sum(case when `v`.`voto` = 'A FAVOR' then 1 else 0 end) * 100.0 / nullif(sum(case when `v`.`voto` in ('A FAVOR','EN CONTRA') then 1 else 0 end),0),2) AS `porcentaje_favor` FROM (`votaciones_bloques` `b` left join `votaciones_votos` `v` on(`b`.`id` = `v`.`bloque_id`)) GROUP BY `b`.`id`, `b`.`nombre` ;

-- --------------------------------------------------------

